def merge_duplicate_market_groups(apps, schema_editor):
    SecuritiesGroup = apps.get_model('portfolio', 'SecuritiesGroup')
    SecuritiesItem = apps.get_model('portfolio', 'SecuritiesItem')
    TrackedSymbol = apps.get_model('portfolio', 'TrackedSymbol')

    canonical_by_key = {}
    for group in SecuritiesGroup.objects.all().order_by('id'):
        key = (group.name, group.group_type)
        canonical_group = canonical_by_key.get(key)
        if canonical_group is None:
            canonical_by_key[key] = group
            continue

        TrackedSymbol.objects.filter(source_group_id=group.id).update(source_group_id=canonical_group.id)

        existing_symbols = set(
            SecuritiesItem.objects.filter(group_id=canonical_group.id).values_list('symbol', flat=True)
        )
        max_order = SecuritiesItem.objects.filter(group_id=canonical_group.id).aggregate(max_order=Max('order'))['max_order']
        next_order = 0 if max_order is None else max_order + 1

        for item in SecuritiesItem.objects.filter(group_id=group.id).order_by('order', 'id'):
            if item.symbol in existing_symbols:
                item.delete()
                continue

            item.group_id = canonical_group.id
            item.order = next_order
            item.save(update_fields=['group_id', 'order'])
            existing_symbols.add(item.symbol)
            next_order += 1

        group.delete()


